/* Choose a first-visit language before the native PluginSwitcher starts.
A saved/manual $:/language is authoritative. No extra language control. */
exports.name="forge-browser-language";
exports.platforms=["browser"];
exports.after=["load-modules"];
exports.before=["startup"];
exports.synchronous=true;
exports.startup=function(){
 if($tw.wiki.tiddlerExists("$:/language"))return;
 var language=/^da(?:-|$)/i.test(navigator.language||"")?"da-DK":"en-GB";
 $tw.wiki.addTiddler({title:"$:/language",text:"$:/languages/"+language});
};
